/** Automatic customer-copy text is generated by the compiled Rust output core.
 * JSON account wire copies preserve the historical JS account property order
 * in already-stored payment signatures, without selecting any account in JS.
 */
import { businessCoreCall } from "./tauri-bridge";
import type { State } from "./types";

export type NativeAutomaticMessage = {
  phase: "request" | "payment";
  text: string;
  paymentIssues: string[];
  signature: string;
  validRequestLinks: string[];
};
const accountWire = (state: State) =>
  (state.settings.accounts ?? []).map((account) => ({
    id: account.id,
    json: JSON.stringify(account),
  }));

export function nativeAutomaticMessage(
  state: State, groupId: string, includeLinks = false,
): Promise<NativeAutomaticMessage> {
  return businessCoreCall<NativeAutomaticMessage>(
    "output", "render_automatic_message",
    { state, groupId, includeLinks, accountWire: accountWire(state) },
  );
}

export async function nativePaymentWasCopied(
  state: State, groupId: string,
): Promise<boolean> {
  const result = await businessCoreCall<{ copied: boolean }>(
    "output", "payment_copy_status",
    { state, groupId, accountWire: accountWire(state), mode: "payment_copy_status" },
  );
  return result.copied;
}
